// ===== 依赖导入 =====
// Anthropic 官方 SDK，用于调用 Claude 模型
import Anthropic from "@anthropic-ai/sdk";
// 工具定义表与工具执行器，二者构成 Agent 的「手脚」
import { toolDefinitions, executeTool } from "./tools.js";
// 系统提示词构建器：第 3 章引入，用环境信息增强静态核心提示词
import { buildSystemPrompt } from "./prompt.js";
// 权限检查器：第 6 章引入，在执行工具前做安全拦截
import { checkPermission } from "./permissions.js";
// 上下文压缩器：第 7 章引入，对话历史过长时自动摘要以腾出 token
import { maybeCompact } from "./context.js";
// 记忆召回器：第 8 章引入，根据用户输入检索相关记忆注入提示词
import { recallMemories } from "./memory.js";

// 使用的模型，优先取环境变量，否则回退到默认的 claude-sonnet
const MODEL = process.env.MINI_MODEL || "claude-sonnet-4-5-20250929";


// The whole agent is one class holding a growing message array and a loop.
// 整个 Agent 就是一个类：内部维护一个不断增长的消息数组，外加一个对话循环。
export class Agent {
  // Anthropic SDK 客户端实例，负责实际调用模型 API
  private client: Anthropic;
  // 对话历史：随着对话推进不断累积，每次调用都整体发送给模型
  private messages: Anthropic.MessageParam[] = [];

  // 构造函数：创建 Anthropic 客户端
  constructor() {
    this.client = new Anthropic({
      // API 密钥从环境变量读取
      apiKey: process.env.ANTHROPIC_API_KEY,
      // Optional: point at an Anthropic-compatible relay via ANTHROPIC_BASE_URL.
      // 可选：通过 ANTHROPIC_BASE_URL 指向一个兼容 Anthropic 协议的中转服务。
      baseURL: process.env.ANTHROPIC_BASE_URL,
    });
  }

  // One user turn. Call the model; if it asks for tools, run them and feed the
  // results back; repeat until it answers with plain text.
  // 处理一轮用户对话：调用模型；如果模型请求调用工具，就执行工具并把
  // 结果回传给模型；如此循环，直到模型给出纯文本回复为止。
  async chat(userText: string): Promise<void> {
    // 先把用户的输入追加到对话历史
    this.messages.push({ role: "user", content: userText });

    // 主循环：不断「调用模型 → 处理工具 → 再调用模型」，直到模型不再请求工具
    while (true) {
      // Before each model call, compact the history if it has grown too long.
      // 每次调用模型前，如果历史太长就进行压缩摘要，腾出上下文空间。
      this.messages = await maybeCompact(this.messages, this.client, MODEL);
      let system = buildSystemPrompt(); // 第 3 章起：用 prompt.ts 构建带环境信息的系统提示词
      // Recall memories relevant to what the user just asked, into the prompt.
      // 召回与用户当前问题相关的记忆，拼接到系统提示词末尾。
      system += recallMemories(userText);
      // Build the request once. Passing `tools` is the one line that makes the
      // model tool-aware. Chapter 5 turns the call itself into a stream.
      // 构建一次请求。传入 `tools` 是让模型「感知到工具」的关键那一行。
      // 第 5 章会把这次调用本身改成流式调用。
      const request = {
        model: MODEL,
        max_tokens: 4096,
        system,
        tools: toolDefinitions,
        messages: this.messages,
      };

      // Stream the reply so text shows up as it is generated, then collect the
      // finished message (same shape a non-streaming call would return).
      // 以流式方式获取回复，这样文字会边生成边显示；最后再收集完整的
      // 消息对象（与非流式调用返回的结构完全相同）。
      const stream = this.client.messages.stream(request);
      // 每收到一段文本就立即写入标准输出，实现打字机效果
      stream.on("text", (t) => process.stdout.write(t));
      const reply = await stream.finalMessage();
      process.stdout.write("\n");

      // Record the assistant's full reply (text + any tool calls).
      // 把助手这一轮的完整回复（文本 + 可能的工具调用）记入对话历史。
      this.messages.push({ role: "assistant", content: reply.content });

      // 从回复内容块中筛选出所有工具调用块
      const toolUses = reply.content.filter(
        (b): b is Anthropic.ToolUseBlock => b.type === "tool_use"
      );
      // No tool calls means the model is done with this turn.
      // 没有工具调用，说明模型认为本轮对话结束，直接返回。
      if (toolUses.length === 0) return;

      // Run every requested tool and send the outputs back as one user message.
      // 执行所有被请求的工具，然后把输出结果作为一条 user 消息回传给模型。
      const results: Anthropic.ToolResultBlockParam[] = [];
      for (const tu of toolUses) {
        // 打印正在执行的工具名和参数，方便调试和观察
        console.log(`  → ${tu.name}(${JSON.stringify(tu.input)})`);
        // Check permission before running the tool; a denied call never runs.
        // 执行工具前先检查权限；被拒绝的调用永远不会真正执行。
        const output = checkPermission(tu.name, tu.input as Record<string, any>) === "deny"
          ? `Denied: ${tu.name} was blocked by the permission system.`
          : await executeTool(tu.name, tu.input as Record<string, any>);
        results.push({ type: "tool_result", tool_use_id: tu.id, content: output });
      }
      // 把所有工具结果作为一条 user 消息追加到历史，进入下一轮循环
      this.messages.push({ role: "user", content: results });
    }
  }
  // Session support: expose the history so the CLI can save it and restore it.
  // 会话支持：暴露对话历史，让 CLI 能够保存和恢复会话状态。
  // 获取当前完整对话历史
  history(): Anthropic.MessageParam[] { return this.messages; }
  // 从外部恢复对话历史（如从磁盘加载已保存的会话）
  loadHistory(messages: Anthropic.MessageParam[]): void { this.messages = messages; }
  // 清空对话历史，开始全新会话
  clearHistory(): void { this.messages = []; }
}

// ===== 依赖导入 =====
// Node.js 文件系统模块：读取、写入、判断存在性、创建目录、读取目录、获取文件状态
import { readFileSync, writeFileSync, existsSync, mkdirSync, readdirSync, statSync } from "fs";
// 子进程模块：同步执行 shell 命令
import { execSync, execFileSync } from "child_process";
// glob 库：按通配符模式匹配文件路径
import { glob } from "glob";
// 路径工具：提取目录名、拼接路径
import { dirname, join } from "path";
// Anthropic SDK 的类型定义（仅用于类型，不引入运行时依赖）
import type Anthropic from "@anthropic-ai/sdk";

// A tool is three things: a name, a description the model reads, and a function
// that does the work. The definitions below are exactly the shape the API wants.
// 一个工具由三部分组成：名称、模型可读的描述、以及真正干活的函数。
// 下面的定义结构正是 Anthropic API 所要求的格式。
// 工具定义表：每个条目声明一个工具的名称、描述和输入参数 schema
export const toolDefinitions: Anthropic.Tool[] = [
  {
    // read_file：读取文件内容，返回带行号的文本
    name: "read_file",
    description: "Read the contents of a file. Returns the file content with line numbers.",
    input_schema: {
      type: "object",
      properties: { file_path: { type: "string", description: "The path to the file to read" } },
      required: ["file_path"],
    },
  },
  {
    // write_file：写入文件，不存在则创建，已存在则覆盖
    name: "write_file",
    description: "Write content to a file. Creates it if missing, overwrites if it exists.",
    input_schema: {
      type: "object",
      properties: {
        file_path: { type: "string", description: "The path to the file to write" },
        content: { type: "string", description: "The content to write" },
      },
      required: ["file_path", "content"],
    },
  },
  {
    // edit_file：精确字符串替换；old_string 必须完全匹配且唯一
    name: "edit_file",
    description: "Replace an exact string in a file with new content. old_string must match exactly and be unique.",
    input_schema: {
      type: "object",
      properties: {
        file_path: { type: "string", description: "The path to the file to edit" },
        old_string: { type: "string", description: "The exact string to find" },
        new_string: { type: "string", description: "The string to replace it with" },
      },
      required: ["file_path", "old_string", "new_string"],
    },
  },
  {
    // list_files：按 glob 模式列出匹配的文件
    name: "list_files",
    description: "List files matching a glob pattern (e.g. \"**/*.ts\").",
    input_schema: {
      type: "object",
      properties: {
        pattern: { type: "string", description: "Glob pattern to match files" },
        path: { type: "string", description: "Base directory. Defaults to cwd." },
      },
      required: ["pattern"],
    },
  },
  {
    // grep_search：正则搜索文件内容，返回匹配行及路径和行号
    name: "grep_search",
    description: "Search for a regex pattern in files. Returns matching lines with paths and line numbers.",
    input_schema: {
      type: "object",
      properties: {
        pattern: { type: "string", description: "The regex pattern to search for" },
        path: { type: "string", description: "Directory or file to search. Defaults to cwd." },
      },
      required: ["pattern"],
    },
  },
  {
    // run_shell：执行 shell 命令并返回输出（用于跑测试、git、安装依赖等）
    name: "run_shell",
    description: "Execute a shell command and return its output. For tests, git, package installs, etc.",
    input_schema: {
      type: "object",
      properties: { command: { type: "string", description: "The shell command to execute" } },
      required: ["command"],
    },
  },
];

// Dispatch a tool call by name. Unknown names return an error string instead of
// throwing, so a hallucinated tool name lets the model self-correct.
// 按名称分派工具调用。未知的工具名返回错误字符串而非抛出异常，
// 这样模型面对幻觉出的工具名时可以自行纠错。
// 工具执行入口：根据工具名路由到对应的实现函数
export async function executeTool(name: string, input: Record<string, any>): Promise<string> {
  switch (name) {
    case "read_file": return readFile(input as { file_path: string });
    case "write_file": return writeFile(input as { file_path: string; content: string });
    case "edit_file": return editFile(input as { file_path: string; old_string: string; new_string: string });
    case "list_files": return listFiles(input as { pattern: string; path?: string });
    case "grep_search": return grepSearch(input as { pattern: string; path?: string });
    case "run_shell": return runShell(input as { command: string });
    // 未知工具：返回提示信息而非报错，交给模型自行修正
    default: return `Unknown tool: ${name}`;
  }
}

// 读取文件内容，每行加上行号前缀（格式：行号右对齐4位 + " | " + 内容）
function readFile(input: { file_path: string }): string {
  try {
    const lines = readFileSync(input.file_path, "utf-8").split("\n");
    return lines.map((l, i) => `${String(i + 1).padStart(4)} | ${l}`).join("\n");
  } catch (e: any) {
    // 读取失败时返回错误信息而非抛异常，让模型能感知到问题
    return `Error reading file: ${e.message}`;
  }
}

// 写入文件：如果所在目录不存在则自动创建，然后写入内容
function writeFile(input: { file_path: string; content: string }): string {
  try {
    const dir = dirname(input.file_path);
    // 目录不存在时递归创建，避免写入失败
    if (dir && !existsSync(dir)) mkdirSync(dir, { recursive: true });
    writeFileSync(input.file_path, input.content);
    // 统计写入的行数，在返回信息中告知模型
    const n = input.content.split("\n").length;
    return `Successfully wrote to ${input.file_path} (${n} lines)`;
  } catch (e: any) {
    return `Error writing file: ${e.message}`;
  }
}

// edit_file is the one tool with a real trap: the match must be unique, or you
// edit the wrong place. So we count occurrences and refuse if it isn't unique.
// edit_file 是唯一一个有真正陷阱的工具：匹配必须唯一，否则你会改错地方。
// 因此我们先统计出现次数，不唯一就拒绝执行。
// 编辑文件：将文件中唯一匹配的 old_string 替换为 new_string
function editFile(input: { file_path: string; old_string: string; new_string: string }): string {
  try {
    const content = readFileSync(input.file_path, "utf-8");
    // 完全找不到匹配字符串时报错
    if (!content.includes(input.old_string)) {
      return `Error: old_string not found in ${input.file_path}`;
    }
    // 通过 split 后的段数减一来计算出现次数
    const count = content.split(input.old_string).length - 1;
    // 出现多次则拒绝替换，避免歧义性修改
    if (count > 1) {
      return `Error: old_string found ${count} times in ${input.file_path}. Must be unique.`;
    }
    // split/join avoids $-substitution surprises from String.replace.
    // 用 split/join 而非 String.replace，避免 $ 替换符带来的意外行为。
    const updated = content.split(input.old_string).join(input.new_string);
    writeFileSync(input.file_path, updated);
    return `Successfully edited ${input.file_path}`;
  } catch (e: any) {
    return `Error editing file: ${e.message}`;
  }
}

// 列出匹配 glob 模式的文件（自动排除 node_modules 和 .git）
async function listFiles(input: { pattern: string; path?: string }): Promise<string> {
  try {
    const files = await glob(input.pattern, {
      cwd: input.path || process.cwd(),
      // 不返回目录，只返回文件
      nodir: true,
      // 排除依赖目录和 git 目录，避免噪声
      ignore: ["node_modules/**", ".git/**"],
    });
    if (files.length === 0) return "No files found matching the pattern.";
    // 最多返回 200 个结果，防止输出过长
    return files.slice(0, 200).join("\n");
  } catch (e: any) {
    return `Error listing files: ${e.message}`;
  }
}

// 正则搜索文件内容：返回匹配行及其路径和行号
function grepSearch(input: { pattern: string; path?: string }): string {
  // Prefer the system grep; fall back to a tiny JS walker if it isn't there.
  // 优先使用系统自带的 grep；如果系统没有 grep，则回退到一个简易的 JS 遍历器。
  try {
    const out = execFileSync("grep", ["--line-number", "--color=never", "-r", "--", input.pattern, input.path || "."], {
      encoding: "utf-8", maxBuffer: 10 * 1024 * 1024, timeout: 10000,
    });
    // 过滤空行，最多取 100 条匹配结果
    return out.split("\n").filter(Boolean).slice(0, 100).join("\n") || "No matches found.";
  } catch (e: any) {
    // grep 退出码 1 表示「无匹配」，属于正常情况，不算错误
    if (e.status === 1) return "No matches found.";
    // 其他错误（如 grep 不存在）回退到纯 JS 实现
    return grepJS(input.pattern, input.path || ".");
  }
}

// 纯 JS 实现的 grep：递归遍历目录，逐行做正则匹配（grep 不可用时的后备方案）
function grepJS(pattern: string, dir: string): string {
  let re: RegExp;
  // 先编译正则表达式，无效正则直接返回错误
  try { re = new RegExp(pattern); } catch (e: any) { return `Error: invalid regex: ${e.message}`; }
  const matches: string[] = [];
  // 递归遍历目录的内部函数
  const walk = (d: string) => {
    let entries: string[];
    try { entries = readdirSync(d); } catch { return; }
    for (const name of entries) {
      // 跳过隐藏文件和 node_modules 目录
      if (name.startsWith(".") || name === "node_modules") continue;
      const full = join(d, name);
      let st; try { st = statSync(full); } catch { continue; }
      // 如果是目录则递归遍历
      if (st.isDirectory()) { walk(full); continue; }
      // 逐行读取文件内容并做正则匹配
      try {
        readFileSync(full, "utf-8").split("\n").forEach((line, i) => {
          if (re.test(line) && matches.length < 100) matches.push(`${full}:${i + 1}:${line}`);
        });
      } catch {}
    }
  };
  walk(dir);
  return matches.length ? matches.join("\n") : "No matches found.";
}

// 执行 shell 命令并返回输出
function runShell(input: { command: string }): string {
  try {
    return execSync(input.command, {
      encoding: "utf-8", maxBuffer: 5 * 1024 * 1024, timeout: 30000,
      stdio: ["pipe", "pipe", "pipe"], shell: "/bin/sh",
    }) || "(no output)";
  } catch (e: any) {
    // 命令失败时返回退出码和 stdout/stderr，方便模型诊断问题
    return `Command failed (exit ${e.status})${e.stdout ? `\nStdout: ${e.stdout}` : ""}${e.stderr ? `\nStderr: ${e.stderr}` : ""}`;
  }
}

// 导入 Node.js 内置的 readline 模块，用于读取用户在终端的逐行输入
import * as readline from "readline";
// 导入 pathToFileURL：把文件路径转成 file:// URL，用于判断脚本是否被直接执行
import { pathToFileURL } from "url";
// 导入核心的 Agent 类，它是整个助手的大脑（负责调用模型和工具）
import { Agent } from "./agent.js";
// 第 4 章起引入：会话的保存与加载，让对话可以跨进程恢复
import { saveSession, loadSession } from "./session.js";
// 第 9 章起引入：技能解析，把 "/name ..." 形式的输入映射到技能模板
import { resolveSkill } from "./skills.js";

// A tiny REPL: read a line, hand it to the agent, repeat. One-shot mode runs a
// single prompt from argv and exits (handy for scripts and testing). Exported as
// runCli(argv) so it can be driven in-process without spawning a shell.
// 一个微型 REPL（读取-求值-打印循环）：读取一行输入，交给 agent 处理，然后重复。
// 单次模式（one-shot）会从命令行参数取一个 prompt 执行一次后退出，
// 这对脚本和测试很方便。导出为 runCli(argv)，这样无需新开 shell 就能在进程内调用它。
export async function runCli(argv: string[] = process.argv.slice(2)): Promise<void> {
  // 检查是否设置了 API Key，没有就提示并退出
  if (!process.env.ANTHROPIC_API_KEY) {
    console.error("Set ANTHROPIC_API_KEY (and optionally ANTHROPIC_BASE_URL) first.");
    process.exit(1);
  }

  // 创建 agent 实例，它是处理消息、调用工具的核心对象
  const agent = new Agent();
  // --resume: reload the saved conversation before doing anything else.
  // --resume：在开始任何操作前，先把上次保存的对话历史加载回来
  const resume = argv.includes("--resume");
  argv = argv.filter((a) => a !== "--resume");
  if (resume) {
    const saved = loadSession();
    if (saved) { agent.loadHistory(saved as any); console.log(`(resumed ${saved.length} messages)`); }
  }

  // 把剩余的命令行参数拼成一个一次性的 prompt
  const oneShot = argv.join(" ").trim();
  if (oneShot) {
    // "/name ..." runs a skill's prompt template; anything else is a plain message.
    // "/name ..." 会触发对应技能的 prompt 模板；其它输入则当作普通消息处理
    const input = resolveSkill(oneShot) ?? oneShot;
    // 把输入交给 agent 进行一次对话
    await agent.chat(input);
    // 对话结束后保存历史，便于下次 --resume 恢复
    saveSession(agent.history());
    return;
  }

  // 进入交互式 REPL 模式：从标准输入读、写到标准输出
  const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
  console.log("mini-claude — type a message, or 'exit' to quit.\n");
  // 用一个 Promise 包住整个问答循环，使函数变成可 await 的异步流程
  await new Promise<void>((resolve) => {
    // ask() 是一个递归的提问函数：每次回答完后再调用自身，实现循环
    const ask = () => {
      rl.question("you: ", async (line) => {
        const input = line.trim();
        // 输入 exit 或 quit 时关闭输入流并结束循环
        if (input === "exit" || input === "quit") { rl.close(); resolve(); return; }
        // /clear：清空对话历史并保存，然后继续提问
        if (input === "/clear") { agent.clearHistory(); saveSession(agent.history()); console.log("(history cleared)"); ask(); return; }
        // 非空输入先尝试解析为技能，否则当作普通消息发送给 agent
        if (input) await agent.chat(resolveSkill(input) ?? input);
        // 每轮对话后保存历史
        if (input) saveSession(agent.history());
        ask();
      });
    };
    ask();
  });
}

// Run only when executed directly (not when imported for tests/demos).
// 只有当本文件被直接执行（而非被测试或示例 import）时才启动 CLI。
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) runCli();

